import React, { useEffect } from "react";
import { AbsoluteFill, Composition, delayRender, continueRender, registerRoot } from "remotion";

const FONT_CSS = "@font-face{font-family:\"Space Grotesk\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Space Grotesk\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Inter\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Inter\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Playfair Display\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Playfair Display\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"DM Sans\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"DM Sans\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"JetBrains Mono\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"JetBrains Mono\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Oswald\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Oswald\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Nunito\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Nunito\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Cormorant Garamond\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Cormorant Garamond\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Roboto Condensed\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Roboto Condensed\";font-style:normal;font-weight:700;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}\n@font-face{font-family:\"Bebas Neue\";font-style:normal;font-weight:400;font-display:swap;src:url(\"data:font/woff2;base64,\") format(\"woff2\");}";
const FS = { w400: "data:font/woff2;base64,", w700: "data:font/woff2;base64," };
const MG_PRESENT = ["Inter","DM Sans","Nunito","JetBrains Mono","Roboto Condensed"];
const TNUMSET = ["Inter","DM Sans","Nunito","JetBrains Mono","Roboto Condensed","Fira Sans","FiraSansDisk"];
const ALLFAMILIES = ["Inter","DM Sans","Nunito","JetBrains Mono","Roboto Condensed","Fira Sans","Arial","FiraSansDisk"];
const HEADLINE = "THE QUICK BROWN FOX JUMPS OVER 0123456789";

function domW(family, weight, tnum) {
  const s = document.createElement("span");
  s.style.fontFamily = '"' + family + '"';
  s.style.fontWeight = weight;
  s.style.fontSize = "48px";
  s.style.fontVariantNumeric = tnum ? "tabular-nums" : "normal";
  s.style.position = "absolute";
  s.style.whiteSpace = "pre";
  s.style.lineHeight = "48px";
  s.textContent = "1234567890";
  document.body.appendChild(s);
  const w = s.getBoundingClientRect().width;
  s.remove();
  return w;
}

function Probe() {
  useEffect(() => {
    const handle = delayRender("measure-current");
    (async () => {
      try {
        const style = document.createElement("style");
        style.textContent = FONT_CSS;
        document.head.appendChild(style);
        const ff400 = new FontFace("FiraSansDisk", "url(" + FS.w400 + ")");
        const ff700 = new FontFace("FiraSansDisk", "url(" + FS.w700 + ")", { weight: "700" });
        const r = await Promise.allSettled([ff400.load(), ff700.load()]);
        r.forEach((x) => { if (x.status === "fulfilled") { document.fonts.add(x.value); } else { console.log("PROBE FiraSansDisk load FAILED: " + x.reason); } });
        await Promise.allSettled([...ALLFAMILIES].flatMap((f) => [400, 700, 800].map((w) => document.fonts.load(w + ' 48px "' + f + '"'))));
        await document.fonts.ready;
        console.log("=====PROBE-BEGIN=====");
        console.log("UA: " + navigator.userAgent);
        console.log("--- A. document.fonts.check (1=face loaded, 0=not) ---");
        ALLFAMILIES.forEach((f) => {
          const row = [400, 700, 800].map((w) => (document.fonts.check(w + ' 48px "' + f + '"') ? "1" : "0"));
          console.log((f + ".padEnd(20)") && f.padEnd(20) + " check 400/700/800: " + row.join(" "));
        });
        console.log("--- B. canvas measureText '0123456789' 48px ---");
        const canvas = document.createElement("canvas");
        const ctx = canvas.getContext("2d");
        ALLFAMILIES.forEach((f) => {
          const row = [400, 700, 800].map((w) => {
            ctx.font = w + ' 48px "' + f + '"';
            return w + ":" + ctx.measureText("0123456789").width.toFixed(1);
          });
          console.log(f.padEnd(20) + " " + row.join("  "));
        });
        console.log("--- C. tabular-nums A/B, DOM width '1234567890' 48px ---");
        TNUMSET.forEach((f) => {
          const n = domW(f, 400, false);
          const t = domW(f, 400, true);
          console.log(f.padEnd(20) + " normal=" + n.toFixed(1) + " tabular=" + t.toFixed(1) + " delta=" + (t - n).toFixed(1));
        });
        console.log("--- D. headline @800 (mg measureText use), DOM width ---");
        console.log("Fira Sans (prod fallback)".padEnd(26) + " " + domW("Fira Sans", 800, false).toFixed(1));
        console.log("FiraSansDisk (real vendored)".padEnd(26) + " " + domW("FiraSansDisk", 800, false).toFixed(1));
        console.log("Arial".padEnd(26) + " " + domW("Arial", 800, false).toFixed(1));
        ["Inter", "DM Sans", "Nunito", "JetBrains Mono", "Roboto Condensed"].forEach((f) => {
          console.log((f + " (loader-registered)").padEnd(26) + " " + domW(f, 800, false).toFixed(1));
        });
        console.log("=====PROBE-END=====");
        continueRender(handle);
      } catch (e) {
        console.log("PROBE ERROR: " + String(e && e.message ? e.message : e));
        continueRender(handle);
      }
    })();
  }, []);
  return (
    <AbsoluteFill style={{ backgroundColor: "#000", color: "#fff", padding: 48, fontFamily: "monospace", fontSize: 14, whiteSpace: "pre", overflow: "hidden" }}>
      <div>measure-current probe - see browser console log for results</div>
    </AbsoluteFill>
  );
}

const Root = () => (
  <Composition id="MeasureCurrent" component={Probe} durationInFrames={1} fps={30} width={1080} height={1920} />
);
registerRoot(Root);
